UPDATE tasks
title = #{fieldValue}, status = #{fieldValue}, progress = #{fieldValue}, start_at = TO_DATE(#{fieldValue}, 'YYYY-MM-DD'), "END" = TO_DATE(#{fieldValue}, 'YYYY-MM-DD'), task_level = #{fieldValue}, updated = SYSDATE
WHERE task_id = #{taskId}

UPDATE sub_tasks
title = #{fieldValue}, status = #{fieldValue}, progress = #{fieldValue}, start_at = TO_DATE(#{fieldValue}, 'YYYY-MM-DD'), "END" = TO_DATE(#{fieldValue}, 'YYYY-MM-DD'), updated = SYSDATE
WHERE sub_task_id = #{subTaskId}
